INSERT INTO `lab_activities` VALUES (1,'Sample collection across Nigerian states','Fieldwork','Blood samples from patients with malaria are collected with partner health facilities, then shipped to IGH for genomic analysis.',NULL,'/home/lab_33.jpg',NULL,1,1,0,NULL,'2026-09-25 15:00:50','2026-09-25 15:00:50'),(2,'Amplicon sequencing at IGH','Laboratory','Parasite DNA is extracted and sequenced in the IGH laboratory to read the genes linked to drug and diagnostic resistance.',NULL,'/home/lab_8.jpg',NULL,1,2,0,NULL,'2026-09-25 15:00:50','2026-09-25 15:00:50'),(3,'From sequences to policy signals','Data','Bioinformatics pipelines turn raw reads into mutation frequencies that are compared with WHO thresholds on this dashboard.',NULL,'/home/lab_29.jpg',NULL,1,3,0,NULL,'2026-09-25 15:00:50','2026-09-25 15:00:50'),(4,'ParaSight','Project','A platform from the lab that brings malaria parasite genomic data together for researchers and public health teams.',NULL,'/home/lab_22.jpg','https://para-sight.org/',0,4,0,NULL,'2026-09-25 15:00:50','2026-09-25 15:00:50');
