--
-- Table structure for table `species_observations`
--

DROP TABLE IF EXISTS `species_observations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `species_observations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `state_id` int(10) unsigned NOT NULL,
  `year` smallint(5) unsigned NOT NULL,
  `source_type` enum('publication','sequencing') NOT NULL,
  `publication_id` int(10) unsigned DEFAULT NULL,
  `sequencing_batch_id` int(10) unsigned DEFAULT NULL,
  `species_combination` varchar(50) NOT NULL,
  `sample_count` int(10) unsigned NOT NULL,
  `upload_id` int(10) unsigned DEFAULT NULL,
  `is_hidden` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_species_state_year` (`state_id`,`year`),
  KEY `fk_species_publication` (`publication_id`),
  KEY `fk_species_batch` (`sequencing_batch_id`),
  KEY `fk_species_upload` (`upload_id`),
  CONSTRAINT `fk_species_batch` FOREIGN KEY (`sequencing_batch_id`) REFERENCES `sequencing_batches` (`id`),
  CONSTRAINT `fk_species_publication` FOREIGN KEY (`publication_id`) REFERENCES `publications` (`id`),
  CONSTRAINT `fk_species_state` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`),
  CONSTRAINT `fk_species_upload` FOREIGN KEY (`upload_id`) REFERENCES `uploads` (`id`),
  CONSTRAINT `chk_species_source` CHECK (`source_type` = 'publication' and `publication_id` is not null and `sequencing_batch_id` is null or `source_type` = 'sequencing' and `sequencing_batch_id` is not null and `publication_id` is null)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

