INSERT INTO `team_members` VALUES (1,'Dr. Ify Aniebo','PI - Malaria team','Associate Professor of Molecular Biology and Genomics, Calestous Juma Science Leadership Fellow','Dr. Ifeyinwa Aniebo developed the concept of this molecular surveillance reporting tool as Principal Investigator, with a five-year grant from the Bill and Melinda Gates Foundation. Her lab at the Institute of Genomics and Global Health tracks antimalarial drug resistance and diagnostic resistance across Nigeria.','/team/ify_aniebo.jpg',NULL,'https://www.linkedin.com/in/ifyaniebo/',1,0,0,'2026-09-25 13:39:33','2026-09-28 08:36:02'),(2,'Dr. Vera Mitesser','Postdoctoral Researcher','Institute of Genomics and Global Health, Redeemer\'s University','Dr. Vera Mitesser is a postdoctoral researcher at the Institute of Genomics and Global Health (IGH) in Ede, Nigeria. She earned her PhD from the Hebrew University of Jerusalem, Israel, in January 2023. Her doctoral research focused on the basic biology of Plasmodium, the parasite that causes human malaria, and in particular on transcriptional regulation and DNA compaction.\n\nAfter her PhD, she turned to the analysis of field samples from malaria-endemic regions. She now studies the genetic mechanisms behind antimalarial drug resistance and diagnostic evasion in endemic settings. Convinced that high-quality research must also be carried out within the countries affected by malaria, she moved permanently to Nigeria, where she contributes to strengthening local research capacity and scientific infrastructure.\n\nAlongside her expertise in molecular biology techniques, she has bioinformatics skills and experience in mentoring students and junior researchers, coordinating projects, leading teams and supervising collaborative research. Her publications span several areas of infectious disease research, often as part of interdisciplinary collaborations.\n\nDuring her PhD, she held a two-year fellowship from the Minerva Foundation, which supports German-Israeli scientific cooperation under the umbrella of the Max Planck Society. She has also contributed to several grant applications, including a successful proposal to the U.S.-Israel Binational Science Foundation (BSF) built on the findings of her doctoral research.','/team/vera_mitesser.jpg',NULL,'https://www.linkedin.com/in/vera-mitesser-a1403119b/',0,1,0,'2026-09-25 13:39:33','2026-09-28 13:20:49'),(3,'Khadim Gueye','Senior Bioinformatician','Institute of Genomics and Global Health, Redeemer\'s University','Khadim Gueye is a Senior Bioinformatician at the Institute of Genomics and Global Health (IGH) in Nigeria, where he leads the computational analysis of national malaria genomic surveillance data within the Ify Aniebo Lab. His work focuses on antimalarial drug resistance, parasite genetic diversity, population genomics and gene flow, and on translating these results into evidence for malaria control policy. He is also the Co-Founder and Chief Executive Officer of ABCOMICS, an initiative dedicated to strengthening bioinformatics capacity across Africa.\n\nMr Gueye brings eight years of experience in genomic epidemiology and data science across Africa and Europe. At EMBL-EBI in the United Kingdom, he served as a bioinformatician for the European Nucleotide Archive, ensuring the quality of genomic data submitted by the international research community. At IRESSEF in Senegal, he led the bioinformatics team for national SARS-CoV-2 genomic surveillance, contributing to the first detection of a Variant of Concern in the country. He previously studied Plasmodium falciparum population genetics at the MRC Unit The Gambia at the London School of Hygiene and Tropical Medicine.\n\nHe holds a Master\'s degree in Bioinformatics and Biomathematics from Cheikh Anta Diop University of Dakar and has co-authored twelve peer-reviewed publications, including contributions to Nucleic Acids Research.','/team/khadim_gueye.jpg',NULL,'https://www.linkedin.com/in/khadimgueyekgy/',0,2,0,'2026-09-25 13:39:33','2026-09-28 08:36:02'),(4,'John Openibo','Research Scientist','Institute of Genomics and Global Health, Redeemer\'s University','John O. Openibo is a Research Scientist at the Institute of Genomics and Global Health (IGH, formerly ACEGID), with more than ten years of experience in infectious disease research. He studied Microbiology at Lagos State University (BSc) and Covenant University (MSc), and his work is guided by Sustainable Development Goal 3: good health and well-being.\n\nDuring his studies, he received the Lagos State University academic scholarship three times, the Lagos State Indigene undergraduate scholarship twice and the Lagos State postgraduate academic scholarship once. He was also awarded The World Academy of Sciences and Covenant University Bioinformatics Research (TWAS-CUBRe) Postgraduate Fellowship.\n\nHis research covers tuberculosis, malaria and SARS-CoV-2, from diagnosis and drug testing to therapeutic efficacy studies and genomic surveillance. He is skilled in the use of microbiology, molecular biology and genomics equipment for diagnosis and research, and has several scientific certifications and publications to his credit. He also takes part in public health campaigns on infectious and non-communicable diseases, and has worked both as a team lead and as a team member on research projects.','/team/john_openibo.jpg',NULL,'https://www.linkedin.com/in/john-openibo-160ba0141/',0,3,0,'2026-09-25 13:39:33','2026-09-28 12:24:46'),(5,'Adedayo Adesida','PhD student','Institute of Genomics and Global Health, Redeemer\'s University','Adedayo is a PhD research fellow at the Institute of Genomics and Global Health. His research interest is on the applications of molecular biology, genomics and bio-informatics tools to understudy the dynamics of transmission of parasitic agents and the identification of molecular markers that mediate parasites\' resistance and host susceptibility.\n\nHis PhD research is on molecular surveillance and translational modeling of antimalarial drug and diagnostic resistance.','/team/adedayo_adesida.jpg',NULL,'https://www.linkedin.com/in/adedayo-adesida/',0,4,0,'2026-09-28 08:36:02','2026-09-28 09:18:59');
/*!40000 ALTER TABLE `team_members` ENABLE KEYS */;
UNLOCK TABLES;

